def restore_ip_addresses(s):
    result = []

    def backtrack(index, current_ip, dots):
        if dots == 4:
            if index == len(s):
                result.append(current_ip[:-1])
            return

        if index >= len(s):
            return

        for i in range(1, 4):
            if index + i > len(s):
                continue
            segment = s[index:index + i]
            if segment[0] == '0' and len(segment) > 1:
                continue
            if int(segment) <= 255:
                backtrack(index + i, current_ip + segment + ".", dots + 1)

    backtrack(0, "", 0)
    return result

