def ternary_search(arr, key):
    def search(left, right):
        if left > right:
            return -1

        if left == right:
            if arr[left] == key:
                return left
            else:
                return -1

        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        elif arr[mid2] == key:
            return mid2
        elif key < arr[mid1]:
            return search(left, mid1 - 1)
        elif key > arr[mid2]:
