def knapsack_memoization(capacity, weights, values):
    memo = {}

    def dfs(i, current_capacity):
        if current_capacity <= 0 or i < 0:
            return 0
        if i == 0:
            if current_capacity >= weights[0]:
                return values[0]
            else:
                return 0

        state = (i, current_capacity)
        if state in memo:
            return memo[state]

        if weights[i] > current_capacity:
            memo[state] = dfs(i - 1, current_capacity)
        else:
            memo[state] = max(
                dfs(i - 1, current_capacity),
                dfs(i - 1, current_capacity - weights[i]) + values[i]
            )

        return memo[state]

    return dfs(len(weights) - 1, capacity)

