def can_partition_k_subsets(nums, k):
    total_sum = sum(nums)
    if k == 0 or total_sum % k != 0:
        return False

    target = total_sum // k
    nums.sort(reverse=True)

    if nums[0] > target:
        return False

    used = [False] * len(nums)
    subsets = [0] * k

    def backtrack(index):
        if index >= len(nums):
            return True

        for i in range(k):
            if subsets[i] + nums[index] > target:
                continue
            if i > 0 and subsets[i] == 0 and subsets[i-1] == 0:
                continue
            subsets[i] += nums[index]
            used[index] = True
            if backtrack(index + 1):
                return True
            subsets[i] -= nums[index]
            used[index] = False

            if subsets[i] == 0:
                break

        return False

    return backtrack(0)

