def quicksort(arr):
    if len(arr) <= 1:
        return arr

    def partition(lst, low, high):
        pivot = lst[high]
        i = low
        for j in range(low, high):
            if lst[j] <= pivot:
                lst[i], lst[j] = lst[j], lst[i]
                i += 1
        lst[i], lst[high] = lst[high], lst[i]
        return i

    def quicksort_helper(lst, low, high):
        if low < high:
            pivot_index = partition(lst, low, high)
            quicksort_helper(lst, low, pivot_index - 1)
            quicksort_helper(lst, pivot_index + 1, high)
        return lst

    return quicksort_helper(arr, 0, len(arr) - 1)

