def patience_sort(nums):
    if not nums:
        return []

    piles = []

    def find_pile(num):
        for pile in piles:
            if not pile or pile[-1] <= num:
                return pile
        return None

    for num in nums:
        pile = find_pile(num)
        if pile:
            pile.append(num)
        else:
            piles.append([num])

    sorted_result = []
    while piles:
        min_pile = min(piles, key=lambda x: x[0] if x else float('inf'))
        sorted_result.append(min_pile.pop(0) if min_pile else None)
        if not min_pile:
            piles.remove(min_pile)

    return sorted_result

