def restore_ip_addresses(s):
    result = []

    def backtrack(index, current_ip):
        if index > len(s):
            return
        if index == len(s):
            if len(current_ip.split('.')) == 4:
                result.append(current_ip)
            return

        if len(current_ip.split('.')) == 4:
            return

        for i in range(1, 4):
            if index + i <= len(s):
                octet = s[index:index + i]
                if octet[0] == '0' and len(octet) > 1:
                    continue
                if 0 <= int(octet) <= 255:
                    new_ip = current_ip + '.' + octet if current_ip else octet
                    backtrack(index + i, new_ip)

    backtrack(0, "")
    return result

