def can_partition(nums):
    total_sum = sum(nums)

    if total_sum % 2 == 1:
        return False

    target = total_sum // 2
    memo = {}

    def backtrack(i, current_sum):
        if current_sum > target:
            return False
        if current_sum == target:
            return True

        if i >= len(nums):
            return False

        state = (i, current_sum)
        if state in memo:
            return memo[state]

        result = backtrack(i + 1, current_sum) or backtrack(i + 1, current_sum + nums[i])
        memo[state] = result
        return result

    return backtrack(0, 0)

