    if len(arr) <= 1:
        return arr

    def quicksort(lst):
        if len(lst) <= 1:
            return lst
        pivot = lst[-1]
        left = [x for x in lst[:-1] if x >= pivot]
        right = [x for x in lst[:-1] if x < pivot]
